package cn.hydrogen.launcher;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import java.util.concurrent.*;import org.json.*;
/** Independent companion guard, deliberately without production controller cleanup. */
final class MapRetentionGuardFlow {
 final Instrumentation test;final HandlerThread thread=new HandlerThread("MapGuardTest");final Handler handler;final String fixture="cn.hydrogen.launcher.test";final StringBuilder report=new StringBuilder("API19 independent guard, actual system window and Java SurfaceViews\n");
 MainActivity activity;Config config;String backup;volatile boolean heartbeat=true,proof=true;volatile Messenger remote,token,proxy;volatile long session=SystemClock.elapsedRealtimeNanos(),sequence;int passed,failed;boolean bound;
 MapRetentionGuardFlow(Instrumentation t){test=t;thread.start();handler=new Handler(thread.getLooper());}
 interface Step{void run()throws Exception;}interface Condition{boolean ok()throws Exception;}
 void require(boolean yes,String why){if(!yes)throw new AssertionError(why);}void main(Runnable r){test.runOnMainSync(r);}
 final Messenger client=new Messenger(new Handler(Looper.getMainLooper()){@Override public void handleMessage(Message m){if(m.what==2){remote=m.replyTo;}if(m.what==4&&proof&&m.replyTo!=null)try{Bundle b=new Bundle(m.getData());b.putLong("issued",SystemClock.elapsedRealtime());b.putBoolean("focused",activity!=null&&activity.hasWindowFocus());Message answer=Message.obtain(null,5);answer.setData(b);m.replyTo.send(answer);}catch(RemoteException ignored){}}});
 final Runnable pulse=new Runnable(){public void run(){if(heartbeat&&remote!=null)try{Bundle b=new Bundle();b.putLong("session",session);b.putLong("sequence",sequence);b.putLong("issued",SystemClock.elapsedRealtime());Message m=Message.obtain(null,3);m.setData(b);remote.send(m);}catch(RemoteException ignored){}handler.postDelayed(this,200);}};
 final ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder binder){proxy=new Messenger(binder);try{Message m=Message.obtain(null,78);m.replyTo=client;proxy.send(m);}catch(RemoteException ignored){}}public void onServiceDisconnected(ComponentName n){}};
 JSONObject state()throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] json={null};test.getTargetContext().sendOrderedBroadcast(new Intent("cn.windchaser.fixture.STATE").setPackage(fixture),null,new BroadcastReceiver(){public void onReceive(Context c,Intent i){json[0]=getResultData();latch.countDown();}},handler,0,null,null);require(latch.await(5,TimeUnit.SECONDS)&&json[0]!=null,"state missing");return new JSONObject(json[0]);}
 void await(String title,long timeout,Condition condition)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<end){try{if(condition.ok())return;}catch(AssertionError pending){}Thread.sleep(45);}throw new AssertionError(title+" state="+state());}
 void command(boolean show,boolean park)throws Exception{Bundle b=new Bundle();b.putInt("protocol",8);b.putLong("session",session);b.putLong("sequence",++sequence);b.putLong("issued",SystemClock.elapsedRealtime());b.putBoolean("show",show);b.putBoolean("park",park);b.putParcelable("client",token==null?client:token);b.putInt("x",80);b.putInt("y",60);b.putInt("w",580);b.putInt("h",380);if(remote!=null){Message m=Message.obtain(null,1);m.setData(b);remote.send(m);}else test.getTargetContext().sendBroadcast(new Intent(show?AmapFloatingController.SHOW:AmapFloatingController.CLOSE).setPackage(fixture).putExtras(b));}
 void visible()throws Exception{await("show",10000,()->state().optBoolean("bridge_added")&&!state().optBoolean("parked"));}
 void park()throws Exception{command(false,true);await("park",5000,()->state().optBoolean("bridge_added")&&state().optBoolean("parked"));}
 void reset()throws Exception{session++;sequence=0;token=null;remote=null;heartbeat=proof=true;command(true,false);visible();}
 void check(String title,Step task){android.util.Log.i("MapRetentionGuardTest","START "+title);try{task.run();passed++;report.append("PASS ");}catch(Throwable e){failed++;report.append("FAIL ").append(e).append(" ");}report.append(title).append('\n');}
 void run(){try{
  config=new Config(test.getTargetContext());backup=config.exportJson();config.put("autoRecoverApps",false);config.put("homePage",0);config.put("pageAnimation",false);
  test.getTargetContext().startActivity(new Intent().setComponent(new ComponentName(fixture,"com.autonavi.amapauto.MainMapActivity")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await("fixture",10000,()->!state().optBoolean("paused"));
  activity=(MainActivity)test.startActivitySync(new Intent(test.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));await("launcher focus",10000,()->activity.hasWindowFocus());handler.post(pulse);
  check("visible window still expires with the original 2.5 second lease",()->{reset();heartbeat=proof=false;await("visible lease cleanup",4000,()->!state().optBoolean("bridge_added"));});
  check("parked window expires after bounded internal handoff without heartbeat or proof",()->{reset();park();long begin=SystemClock.elapsedRealtime();heartbeat=proof=false;await("parked lease cleanup",12000,()->!state().optBoolean("bridge_added"));report.append("parked expiry ms=").append(SystemClock.elapsedRealtime()-begin).append('\n');});
  check("remote host Binder death removes a parked window",()->{heartbeat=proof=true;bound=test.getTargetContext().bindService(new Intent().setComponent(new ComponentName(fixture,GuardTokenService.class.getName())),connection,Context.BIND_AUTO_CREATE);require(bound,"proxy bind failed");await("proxy",6000,()->proxy!=null);Thread.sleep(100);session++;sequence=0;remote=null;token=proxy;command(true,false);visible();park();proxy.send(Message.obtain(null,77));await("Binder death cleanup",3000,()->!state().optBoolean("bridge_added"));});
  check("foreground camera withdraws parked map without a launcher hide command",()->{reset();park();test.getTargetContext().startActivity(new Intent().setComponent(new ComponentName(fixture,ReverseCameraActivity.class.getName())).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await("native camera guard",12000,()->!state().optBoolean("bridge_added"));});
 }catch(Throwable e){failed++;report.append("FAIL setup ").append(e).append('\n');}finally{heartbeat=proof=false;handler.removeCallbacks(pulse);if(bound)try{test.getTargetContext().unbindService(connection);}catch(Exception ignored){}if(activity!=null)main(activity::finish);if(backup!=null)try{config.restore(backup);}catch(Exception ignored){}thread.quit();}
 report.append("MAP_RETENTION_GUARD_RESULT passed=").append(passed).append(" failed=").append(failed).append('\n');Bundle out=new Bundle();out.putString("stream",report.toString());test.finish(failed==0?-1:0,out);
 }
}
